#!/bin/bash
# Build the checker and prove `halts_in tm c0 n_steps` (the exact step count). Usage: run_all_x.sh [PARALLEL_JOBS].
# Same switch as run_all.sh. Proof files are in proof_x/ (generated by gen/gen_xfinal.py). Finished jobs are kept.
# To split the jobs over several machines: JOBS=FROM-TO run_all_x.sh N runs only XJ<FROM>..XJ<TO> (and XJHalt when FROM is 0)
# and stops before the final file; afterwards gather all proof_x/XJ*.{vo,vok,done} on one machine and run run_all_x.sh there.
set -u
J=${1:-$(nproc)}
cd "$(dirname "$0")"
export OCAMLPARAM='_,O3=1,inline=1000,unbox-closures=1'
ulimit -s unlimited
die() { echo "run_all_x.sh: $*" >&2; exit 1; }
for c in coqc coq_makefile make ocamlfind; do
  command -v "$c" >/dev/null || die "$c not found in PATH (activate the switch: eval \$(opam env --switch=rocq-fl))"
done
sed -i 's/-native-compiler ondemand/-native-compiler yes/' _CoqProject.x
coq_makefile -f _CoqProject.x -o Makefile.x || die "coq_makefile failed"
[ -f Makefile.x ] || die "coq_makefile did not write Makefile.x"
make -j"$J" -f Makefile.x || die "building theories/ failed"
Q="-native-compiler yes -Q ../base/busycoq BusyCoq -Q ../base/theories BB6 -Q ../theories BF -Q . \"\""
cd proof_x || die "no proof_x/ directory"
eval coqc $Q XCuts.v || die "compiling proof_x/XCuts.v failed"
# A job counts as done only with its .done marker (written after coqc succeeds), so a box lost mid-write cannot leave a bad .vo behind.
run1() { f=$1; b=${f%.v}; [ -f "$b.done" ] && exit 0; rm -f "$b.vo" "$b.vok" "$b.vos" "$b.glob"
  local t0=$(date +%s); eval coqc $Q "$f" > "$b.log" 2>&1 || { echo "FAILED $f"; exit 1; }
  echo "$b $(( $(date +%s) - t0 )) s" > "$b.done"; echo "ok $f $(date +%T)"; }
export -f run1; export Q
if [ -n "${JOBS:-}" ]; then
  F=${JOBS%-*}; T=${JOBS#*-}
  ls XJ*.v | awk -v F="$F" -v T="$T" '{ if ($0=="XJHalt.v") { if (F==0) print } else { n=substr($0,3,4)+0; if (n>=F && n<=T) print } }' \
    | xargs -P "$J" -n 1 bash -c 'run1 "$0"' || die "a job failed (see proof_x/XJ*.log)"
  echo "jobs $JOBS done"; exit 0
fi
ls XJ*.v | xargs -P "$J" -n 1 bash -c 'run1 "$0"' || die "a job failed (see proof_x/XJ*.log)"
eval coqc $(echo "$Q" | sed 's/-native-compiler yes/-native-compiler no/') XFinalProof.v > XFinal.out 2> XFinal.err || { cat XFinal.err >&2; die "compiling proof_x/XFinalProof.v failed"; }
grep -v "^$" XFinal.out
